<?php
declare(strict_types=1);
ob_start();
$escape = static fn (string $value): string => htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
?>
<?php $status = (string) $article->frontMatter->get('status', 'draft'); ?><main class="studio" data-autosave-url="/admin/articles/<?= rawurlencode($article->slug) ?>/draft"><nav class="left-rail" aria-label="Administration"><a class="brand" href="/admin/articles">HolyMD</a><a class="active" href="/admin/articles">Articles</a><a href="/admin/media">Library</a><a href="/admin/settings">Settings</a><footer>Administrator</footer></nav><section class="editor-panel"><div class="editor-topline"><a href="/admin/articles">All articles</a><output id="save-state" aria-live="polite" data-state="saved">Saved draft</output></div><label>Title<input id="article-title" value="<?= $escape($article->title) ?>"></label><label>Date<input id="article-date" type="date" value="<?= $escape((string) $article->frontMatter->get('date')) ?>"></label><label class="markdown-label" for="markdown-body">Markdown</label><textarea id="markdown-body" spellcheck="true"><?= $escape($article->bodyMarkdown) ?></textarea><input id="csrf-token" type="hidden" value="<?= $escape($csrfToken) ?>"></section><section class="preview-panel"><div class="preview-heading"><p class="eyebrow">Live preview</p><div class="publication-actions"><?php if ($status === 'published'): ?><a href="/articles/<?= rawurlencode($article->slug) ?>/">View public</a><form method="post" action="/admin/articles/<?= rawurlencode($article->slug) ?>/withdraw"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><button type="submit" class="secondary">Withdraw</button></form><?php else: ?><form method="post" action="/admin/articles/<?= rawurlencode($article->slug) ?>/publish"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><button id="publish-button" type="submit">Publish</button></form><?php endif; ?></div></div><article id="markdown-preview" class="prose"></article></section><aside class="right-rail"><p class="eyebrow">Version history</p><h2>Restorable drafts</h2><p class="muted">Each save stores a Markdown snapshot.</p><ul class="versions"><?php foreach ($versions as $version): ?><li><form method="post" action="/admin/articles/<?= rawurlencode($article->slug) ?>/restore/<?= $escape($version->value) ?>"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><button type="submit">Restore <?= $escape(substr($version->value, 0, 8)) ?></button></form></li><?php endforeach; ?></ul><?php if ($status === 'draft'): ?><hr><details class="danger-zone"><summary>Delete draft</summary><p>This permanently removes the Markdown file. Type <strong><?= $escape($article->slug) ?></strong> to confirm.</p><form method="post" action="/admin/articles/<?= rawurlencode($article->slug) ?>/delete"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><input name="confirm_slug" required autocomplete="off"><button class="danger" type="submit">Delete draft</button></form></details><?php endif; ?><hr><p class="eyebrow">GEO review</p><p class="muted">Metadata review is available after a saved version. It never writes prose.</p></aside></main>
